class CorpusUnicodeService final : public flight::UnicodeService {
public:
 std::u16string lower(std::u16string_view input) const override { std::u16string out(input); for(auto& c:out) { if(c>=u'A' && c<=u'Z') c=static_cast<char16_t>(c+32); else if(c==u'\u00c9')c=u'\u00e9'; } return out; }
 std::u16string upper(std::u16string_view input) const override { std::u16string out(input); for(auto& c:out) { if(c>=u'a' && c<=u'z') c=static_cast<char16_t>(c-32); else if(c==u'\u00e9')c=u'\u00c9'; } return out; }
};
struct UnicodeFailure { int code = 42; };
class FailingUnicodeService final : public flight::UnicodeService {
public:
 explicit FailingUnicodeService(std::shared_ptr<UnicodeFailure> failure) : failure_(std::move(failure)) {}
 std::u16string lower(std::u16string_view) const override { throw failure_; }
 std::u16string upper(std::u16string_view) const override { throw failure_; }
private:
 std::shared_ptr<UnicodeFailure> failure_;
};
